import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import test from 'node:test';

import { parseLrc } from '../src/lrc.js';
import { readTags } from '../src/tags.js';

// The demo is the first thing anyone sees, and it is generated by a script and
// remuxed by hand. These tests exist so a bad remux fails CI instead of
// shipping a player whose demo has no cover and no title.

const mp3 = new Uint8Array(readFileSync(new URL('../demo/demo.mp3', import.meta.url)));
const lrc = readFileSync(new URL('../demo/demo.lrc', import.meta.url), 'utf8');

test('the demo track carries the tags the player reads', () => {
  const tags = readTags(mp3, 'demo.mp3');
  assert.equal(tags.title, 'Glass');
  assert.equal(tags.artist, 'IZGIV');
  assert.equal(tags.album, 'Demo');
});

test('the demo track has cover art the browser can decode', () => {
  const { picture } = readTags(mp3, 'demo.mp3');
  assert.ok(picture, 'no embedded picture');
  assert.ok(picture.data.length > 1024, `picture is only ${picture.data.length} bytes`);

  const isPng = picture.data[0] === 0x89 && picture.data[1] === 0x50;
  const isJpeg = picture.data[0] === 0xff && picture.data[1] === 0xd8;
  assert.ok(isPng || isJpeg, 'the picture is neither PNG nor JPEG');
  assert.match(picture.mime, /^image\/(png|jpeg)$/);
});

test('the demo file is a plausible size for a web page', () => {
  // It ships in the repository and loads on first paint. A cover embedded as a
  // raw PNG once pushed this to 900 kB; the budget keeps that from returning.
  assert.ok(mp3.length < 600 * 1024, `the demo is ${Math.round(mp3.length / 1024)} kB`);
});

test('the demo lyrics are timed across the whole track', () => {
  const { lines, meta } = parseLrc(lrc);
  assert.equal(meta.ti, 'Glass');
  assert.ok(lines.length >= 6, `only ${lines.length} lines`);

  for (let i = 1; i < lines.length; i += 1) {
    assert.ok(lines[i].time > lines[i - 1].time, `line ${i} is out of order`);
  }
  // The last line should still be inside the 24 second track.
  assert.ok(lines[lines.length - 1].time < 24, 'a lyric line starts after the track ends');
});
